// C implementation of vstodo cmdPush header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_push.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_push.go.\n\n#ifndef VSTODO_C_CMD_PUSH_H\n#define VSTODO_C_CMD_PUSH_H\n\n// Push the current branch to a remote repository.\n// Equivalent to Go cmdPush function.\n// app — vstodo application context pointer\n// args — remote name and branch arguments\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_push(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_PUSH_H